style.css:
@-moz-document domain("roblox.com") {
/* Page background */
body {
    background: #ffe4f1 !important;
    color: #5a2a3a !important;
    font-family: "Comic Sans MS", "Segoe UI", sans-serif !important;
}

/* Top navigation */
.navbar,
.rbx-navbar {
    background: #ffc1dd !important;
    border-bottom: 2px solid #ff9ecb !important;
}

/* Game cards */
.game-card-container,
.item-card-container,
.card-item {
    background: #fff0f7 !important;
    border-radius: 16px !important;
    border: 2px solid #ffb6d9 !important;
    box-shadow: 0 4px 10px rgba(255, 182, 217, 0.5) !important;
    transition: transform 0.2s ease !important;
}

/* Hover effect */
.game-card-container:hover,
.item-card-container:hover {
    transform: scale(1.05) !important;
}

/* Buttons */
button,
.btn-primary-md,
.btn-secondary-md {
    background: linear-gradient(135deg,#ff9ecb,#ff6fb5) !important;
    border: none !important;
    border-radius: 12px !important;
    color: white !important;
    font-weight: bold !important;
}

/* Links */
a {
    color: #ff4fa3 !important;
}

a:hover {
    color: #ff2a8c !important;
}

/* Search bar */
input[type="text"] {
    background: #fff0f7 !important;
    border: 2px solid #ffb6d9 !important;
    border-radius: 10px !important;
    color: #5a2a3a !important;
}

/* Sidebar / content areas */
.left-col,
.content,
.container-main {
    background: #ffe4f1 !important;
}

/* Footer */
footer {
    background: #ffc1dd !important;
    color: #5a2a3a !important;
}
}
